/**
 * Typed access to src/data/dod-cost-data.json, generated by scripts/build-dod-data.mjs
 * from the DoD Facilities Pricing Guide. Do not edit the JSON by hand.
 */
import raw from "../data/dod-cost-data.json"

export type Benchmark = {
  id: string
  table: "Table 2" | "Table 3"
  kind: string
  section: string
  title: string
  /** National average (ACF 1.0) cost per gross square foot, in priceBasis dollars. */
  usdPerSf: number
  priceBasis: string
  escalation: "milcon" | "prv"
  referenceSizeSf: number | null
  stdDevPct: number | null
  projects: number | null
  basisNote: string
  sourceDoc: string
}

export type SiteItem = { code: string; description: string; unit: string; usd: number; priceBasis: string }

export type CountyAcf = { name: string; acf: number; min: number; max: number; installations: number; cities: string[]; aliasOf?: string }
export type StateAcf = { name: string; counties: Record<string, CountyAcf>; median: number; min: number; max: number; countyCount: number }
export type CountryAcf = { median: number; min: number; max: number; installations: number }

export type DodData = {
  generatedAt: string
  source: {
    publisher: string
    distribution: string
    landingPage: string
    files: { doc: string; url: string }[]
    caveat: string
    includes: string[]
    excludes: string[]
  }
  benchmarks: Benchmark[]
  /** DoD Table 6 supporting-facility unit costs (national, Oct 2025 $), keyed by item code. */
  siteItems: Record<string, SiteItem>
  escalation: Record<"milcon" | "prv", { base: string; factors: Record<string, number> }>
  acf: { conus: Record<string, StateAcf>; oconus: Record<string, CountryAcf> }
}

export const dod = raw as unknown as DodData
export const benchmarkById = new Map(dod.benchmarks.map((b) => [b.id, b]))

/** County match key. Must match normCounty() in scripts/build-dod-data.mjs. Pass the Census full name ("Norfolk city"). */
export const normCounty = (s: string) =>
  s
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/\s*\(city\)/g, " city")
    .replace(/^ind\.?\s*city-/, "")
    .replace(/\bcity and borough\b|\bcensus area\b|\b(county|parish|borough|municipality|municipio)\b/g, "")
    .replace(/\bsaint\b/g, "st")
    .replace(/[^a-z0-9]/g, "")

/** Years the escalation tables cover (shared by both tables). */
export const escalationYears = Object.keys(dod.escalation.milcon.factors)
  .filter((y) => y in dod.escalation.prv.factors)
  .map(Number)
  .sort()

export function escalationFactor(b: Benchmark, year: number): number {
  return dod.escalation[b.escalation].factors[String(year)] ?? 1
}
